LOCAL={
'vi':['Ngày','Lịch trình tham khảo','Chuẩn bị và đặt dịch vụ','Kiểm tra giờ mở cửa, thời tiết, điều kiện vé và quy định nhập cảnh áp dụng cho quốc tịch của bạn trước khi đặt. Lịch dưới đây là gợi ý tự túc; không bao gồm vé hoặc dịch vụ.'],
'en':['Day','Suggested itinerary','Planning and booking','Check opening hours, weather, ticket conditions and entry rules for your nationality before booking. This is an independent itinerary idea; tickets and services are not included.'],
'zh':['第','行程参考','准备与预订','预订前请确认开放时间、天气、票务条件及适用于您国籍的入境规定。行程仅供自由行参考，不包含门票或服务。'],
'zh-Hant':['第','行程參考','準備與預訂','預訂前請確認開放時間、天氣、票券條件及適用於您國籍的入境規定。行程僅供自由行參考，不包含門票或服務。'],
'ru':['День','Пример маршрута','Подготовка и бронирование','Перед бронированием проверьте часы работы, погоду, условия билетов и правила въезда для вашего гражданства. Это идея самостоятельной поездки; билеты и услуги не включены.'],
'ko':['일','추천 일정','준비와 예약','예약 전 운영 시간, 날씨, 티켓 조건과 국적에 따른 입국 규정을 확인하세요. 개별 여행을 위한 제안이며 티켓이나 서비스가 포함되지 않습니다.'],
'ja':['日','旅程の提案','準備と予約','予約前に営業時間、天候、チケット条件、国籍に応じた入国規則を確認してください。個人旅行の提案であり、チケットやサービスは含まれません。'],
'hi':['दिन','यात्रा सुझाव','तैयारी और बुकिंग','बुकिंग से पहले खुलने का समय, मौसम, टिकट की शर्तें और अपनी राष्ट्रीयता के लिए प्रवेश नियम जाँचें। यह स्वतंत्र यात्रा का सुझाव है; टिकट या सेवाएँ शामिल नहीं हैं।'],
'fr':['Jour','Itinéraire suggéré','Préparation et réservation','Vérifiez horaires, météo, conditions des billets et règles d’entrée selon votre nationalité avant de réserver. Ce parcours indépendant ne comprend ni billets ni services.'],
'de':['Tag','Routenvorschlag','Planung und Buchung','Vor der Buchung Öffnungszeiten, Wetter, Ticketbedingungen und Einreisebestimmungen für die eigene Staatsangehörigkeit prüfen. Dies ist eine Idee für eine selbstständige Reise; Tickets und Leistungen sind nicht enthalten.'],
'es':['Día','Itinerario sugerido','Preparación y reservas','Antes de reservar, comprueba horarios, tiempo, condiciones de entradas y normas de entrada para tu nacionalidad. Es una propuesta de viaje independiente; no incluye entradas ni servicios.'],
'th':['วัน','แผนเที่ยวแนะนำ','เตรียมตัวและจอง','ตรวจสอบเวลาเปิด อากาศ เงื่อนไขบัตรและกฎเข้าประเทศตามสัญชาติของคุณก่อนจอง นี่เป็นไอเดียเที่ยวด้วยตัวเอง ไม่รวมบัตรหรือบริการ'],
'id':['Hari','Rencana perjalanan','Persiapan dan pemesanan','Periksa jam buka, cuaca, syarat tiket dan aturan masuk sesuai kewarganegaraan sebelum memesan. Ini ide perjalanan mandiri; tiket dan layanan tidak termasuk.']}
VI_SECTIONS=[
[('Ngày 1: Đại Nội và một buổi chiều nhẹ','Dành buổi đầu cho khu Đại Nội theo phạm vi vé thực tế, đi bộ vừa sức và chừa thời gian tránh nắng. Sau đó nghỉ chân, thử món Huế phù hợp khẩu vị hoặc dạo một đoạn bên sông Hương. Xem nội quy, giờ vào cửa và điều kiện thời tiết trước khi khởi hành.'),('Ngày 2: sông Hương và chùa Thiên Mụ','Chọn phương án di chuyển tới chùa Thiên Mụ phù hợp. Nếu dùng thuyền, hỏi rõ bến đón, tuyến, thời lượng và phương án hủy khi thời tiết xấu. Ăn mặc phù hợp ở nơi thờ tự, giữ yên tĩnh và không mặc định vé thuyền đã bao gồm mọi dịch vụ khác.'),('Ngày 3: chọn một lăng tẩm hoặc nghỉ thêm','Chọn một điểm ngoài trung tâm theo sở thích thay vì chạy qua nhiều lăng trong buổi sáng. So sánh quãng đường, vé và xe; nếu bay hoặc đi tàu sau đó, ưu tiên khoảng đệm. Với bún bò, bánh Huế hoặc chè, hỏi thành phần và mức giá trước khi gọi.')],
[('Ngày 1: đến nơi và xác nhận tuyến','Đặt địa chỉ lưu trú, cảng đón và điểm cần tới lên bản đồ. Xác nhận tên cảng, giờ có mặt và cách liên hệ với đơn vị vận hành. Không tự suy rằng mọi tour từ Hạ Long đều bao gồm Cát Bà hoặc vịnh Lan Hạ.'),('Ngày 2: hành trình trên vịnh theo xác nhận','Dùng đúng lịch và tuyến trong vé hoặc xác nhận đặt chỗ. Mang đồ chống nắng, đọc hướng dẫn áo phao và hỏi trước về hành lý, đồ ăn cùng các hoạt động tùy chọn. Hoạt động trên biển phụ thuộc thời tiết; quyết định khai thác và thông báo của đơn vị vận hành cần được ưu tiên.'),('Ngày 3: Cát Bà nếu phù hợp, hoặc chừa ngày về','Chỉ thêm Cát Bà nếu bạn đã xác nhận được tuyến đường bộ, phà hoặc tàu tương ứng và có đủ thời gian. Nếu lịch nối chuyến chặt, chọn một vùng làm trọng tâm thay vì cố ghép cả hai. Dành thời gian dự phòng trước chặng đường dài hoặc chuyến bay.')],
[('Ngày 1: Higashiyama và khu vực Kiyomizu-dera','Nhóm các điểm đi bộ ở phía đông Kyoto vào cùng một ngày và chọn vài điểm ưu tiên. Kiểm tra giờ vào cửa với từng nơi; phố dốc, bậc thang và lượng khách có thể làm thời gian đi dài hơn dự kiến. Tôn trọng biển cấm chụp ảnh và khu vực riêng tư.'),('Ngày 2: Fushimi Inari rồi trở về trung tâm','Đi theo tuyến được phép và chỉ chọn quãng đi bộ vừa sức; không cần hoàn thành mọi đoạn đường để có một chuyến đi ý nghĩa. Sau đó dành buổi còn lại cho ăn uống hoặc một khu phố trung tâm, tính cả thời gian đổi tuyến giao thông.'),('Ngày 3: Arashiyama hoặc giữ lịch linh hoạt','Dành một buổi riêng cho khu Arashiyama và kiểm tra phương tiện từ chỗ ở. Mùa hoa và màu lá thay đổi theo năm, không mặc định poster minh họa phản ánh đúng thời tiết ngày đi. Nếu có tàu hoặc chuyến bay tiếp theo, giữ khoảng đệm trước khi rời Kyoto.')],
[('Ngày 1: bờ sông Seine và khu Eiffel','Chọn một đoạn dạo ven sông, sau đó khám phá khu quanh tháp Eiffel. Việc ngắm từ bên ngoài khác với vé lên tháp; kiểm tra đúng loại vé và khung giờ nếu muốn vào tham quan. Để thời gian cho ăn uống, kiểm tra tuyến về chỗ ở và đi bộ vừa sức.'),('Ngày 2: một bảo tàng và khu phố lân cận','Chỉ chọn một bảo tàng chính theo sở thích, chẳng hạn Louvre hoặc Musée d’Orsay. Kiểm tra ngày mở cửa, thời gian đặt trước và quy định túi xách trên nguồn chính thức. Không coi một ngày là đủ để xem mọi bộ sưu tập hoặc ghép hai bảo tàng lớn chỉ vì chúng xuất hiện trên cùng bản đồ.'),('Ngày 3: Montmartre và những khoảng nghỉ','Dành buổi khám phá khu Montmartre, cân nhắc các đoạn dốc và phương án giao thông. Chừa thời gian cho quán cà phê, ăn uống hoặc tìm hiểu phố xá; kiểm tra giá thực đơn và những khoản tính thêm trước khi gọi.'),('Ngày 4: ngày linh hoạt trước chặng về','Giữ một buổi cho điểm còn thiếu hoặc nghỉ ngơi, tùy giờ rời Paris. Xác nhận đúng sân bay hoặc nhà ga, tính cả thời gian di chuyển và thủ tục. Thẻ vận tải hoặc vé tham quan chỉ hữu ích khi phù hợp đúng tuyến và ngày sử dụng của bạn.')],
[('Ngày 1: Midtown và một cụm đi bộ','Chọn vài điểm trong Midtown Manhattan và một khoảng nghỉ như Bryant Park. Nếu muốn lên đài quan sát, kiểm tra đúng tòa nhà, giờ và điều kiện vé. Giá niêm yết ban đầu có thể khác tổng tiền cuối cùng; đọc trước thuế và phụ phí thay vì suy ra từ ảnh quảng cáo.'),('Ngày 2: Central Park và một bảo tàng','Dành một phần ngày cho công viên, rồi chọn một bảo tàng phù hợp thay vì chạy qua nhiều nơi. Kiểm tra giờ mở cửa và điều kiện đặt vé từ nguồn chính thức. Dự trù thời gian đi bộ và thay đổi thời tiết trong ngày.'),('Ngày 3: Lower Manhattan và Brooklyn Bridge','Nhóm các điểm ở Lower Manhattan, rồi cân nhắc đi bộ qua Brooklyn Bridge nếu sức khỏe và thời tiết phù hợp. Đi đúng lối dành cho người đi bộ và giữ khoảng trống cho dòng người. Không mặc định quãng đường đi bộ thực tế chỉ bằng khoảng cách thẳng trên bản đồ.'),('Ngày 4: một khu Brooklyn hoặc chuyến phà phù hợp','Chọn một khu phố hoặc tuyến phà theo thông tin vận hành hiện tại, không ghép nhiều bến trong ngày bay. Phân biệt tuyến giao thông công cộng và sản phẩm tham quan riêng khi mua vé. Xác nhận sân bay, phương án xe hoặc tàu và giờ rời chỗ ở với đủ thời gian dự phòng.')],
[('Ngày 1: Circular Quay và The Rocks','Bắt đầu từ khu Circular Quay rồi dạo The Rocks, chọn quãng đường vừa sức. Có thể ngắm Sydney Opera House từ bên ngoài; tour vào trong hoặc chương trình biểu diễn cần kiểm tra vé riêng. Xem điều kiện nắng, mang nước và dành thời gian nghỉ.'),('Ngày 2: chọn Manly hoặc Bondi','Chọn một tuyến ven biển chính theo chỗ ở và thời tiết. Nếu đi Manly, kiểm tra lịch phà; nếu chọn Bondi, xem hướng dẫn giao thông và điều kiện đường đi bộ. Chỉ bơi ở nơi được phép theo hướng dẫn cứu hộ và biển cảnh báo; một bãi biển đẹp trong poster không nói lên độ an toàn ngày đi.'),('Ngày 3: vườn thực vật và thời gian linh hoạt','Dành một buổi nhẹ quanh khu Royal Botanic Garden hoặc chọn điểm còn thiếu ở trung tâm. Kiểm tra thông báo ra vào và tuyến đi bộ hiện tại. Nếu rời Sydney trong ngày, xác nhận nhà ga hoặc sân bay và chừa thời gian dự phòng, không xếp một chuyến đi xa sát giờ bay.')]
]
EN_SECTIONS=[
[('Day one: the Imperial City and an easy afternoon','Allow time for the Imperial City within the actual ticket scope and leave breaks for heat and walking. Follow with a manageable riverside outing or Hue food that suits your diet. Check current admission hours, rules and weather before departure.'),('Day two: the Perfume River and Thien Mu','Choose suitable transport to Thien Mu Pagoda. For a boat outing, confirm the pier, route, duration and bad-weather policy. Dress appropriately at places of worship and do not assume a boat ticket includes other visits or services.'),('Day three: one royal tomb or more rest','Choose one out-of-centre visit around your interests instead of rushing between several tombs. Compare transport and ticket requirements, and leave a buffer before a train or flight. Ask about ingredients and prices before ordering Hue dishes or desserts.')],
[('Day one: arrive and confirm the route','Map your accommodation, pickup port and intended stops. Confirm the exact port name, meeting time and operator contact. Do not assume a Ha Long departure automatically includes Cat Ba or Lan Ha Bay.'),('Day two: your confirmed bay itinerary','Follow the route and schedule in your booking confirmation. Read life-jacket instructions and check luggage, meals and optional activities in advance. Sea conditions can change operations; follow official notices and the operator’s decision.'),('Day three: Cat Ba if practical, or a return buffer','Add Cat Ba only after confirming the relevant road, ferry or boat connection and allowing enough time. With a tight onward journey, choose one area instead of forcing both into the trip. Keep a buffer before a long transfer or flight.')],
[('Day one: Higashiyama and Kiyomizu-dera area','Group eastern Kyoto walks into one day and choose a few priorities. Check each site’s opening hours; slopes, steps and crowds can extend the journey. Respect photography restrictions and private areas.'),('Day two: Fushimi Inari and central Kyoto','Follow permitted paths and choose a walk that suits your fitness rather than trying to complete every section. Leave the remaining day for food or a central neighbourhood, including time for transport changes.'),('Day three: Arashiyama or a flexible morning','Give Arashiyama a separate outing and check the route from your accommodation. Blossom and foliage timing changes each year; the illustrated poster does not predict conditions on your travel dates. Leave a buffer before your next train or flight.')],
[('Day one: the Seine and Eiffel Tower area','Choose a manageable riverside walk and explore around the Eiffel Tower. An exterior view differs from admission; check the exact ticket and time slot for an interior visit. Leave room for meals and the journey back.'),('Day two: one museum and its neighbourhood','Choose one major museum, such as the Louvre or Musée d’Orsay, around your interests. Check official opening days, booking times and bag rules. Do not expect to cover every collection or combine two major museums merely because both appear on a map.'),('Day three: Montmartre at an easy pace','Allow time for slopes and transport in Montmartre. Keep breaks for cafes, meals and neighbourhood exploration, checking menus and additional charges before ordering.'),('Day four: flexibility before departure','Use a final morning for a missed stop or rest, according to your actual departure time. Confirm the airport or station and include transport and processing time. A pass is useful only if its coverage and dates suit your route.')],
[('Day one: a Midtown walking cluster','Choose a few Midtown Manhattan stops and a break around Bryant Park. For an observation deck, confirm the exact building, admission time and ticket conditions. Check taxes and fees rather than assuming the first displayed price is final.'),('Day two: Central Park and one museum','Combine part of the park with one museum that matches your interests. Check official hours and admission requirements. Allow enough walking time and adapt to the day’s weather.'),('Day three: Lower Manhattan and Brooklyn Bridge','Group Lower Manhattan stops, then consider the bridge walk if fitness and conditions suit. Follow the pedestrian route and leave room for other walkers. Straight-line map distances do not represent the full walking journey.'),('Day four: a Brooklyn neighbourhood or suitable ferry','Choose one neighbourhood or a currently operating ferry route, avoiding several waterfront transfers before a flight. Distinguish public transport from separate sightseeing products. Confirm the airport and route with a sensible departure buffer.')],
[('Day one: Circular Quay and The Rocks','Begin around Circular Quay and take a manageable walk through The Rocks. Viewing the Opera House exterior differs from an interior tour or performance, which needs its own booking check. Bring water and adapt to heat and sun.'),('Day two: choose Manly or Bondi','Choose one coastal outing around your accommodation and the weather. Check ferry schedules for Manly or the transport and walking route for Bondi. Swim only where permitted, following lifeguards and warning signs; an attractive poster does not indicate safe swimming conditions.'),('Day three: the gardens and flexible city time','Plan an easy outing around the Royal Botanic Garden or a remaining central stop, checking current access notices. If leaving the city that day, confirm the terminal or airport and keep a departure buffer instead of scheduling a distant trip before flying.')]
]
def day_label(lang,day):
    if lang in ('zh','zh-Hant'):return f'第{day}天'
    if lang=='ja':return f'{day}日目'
    if lang=='ko':return f'{day}일차'
    return f'{LOCAL[lang][0]} {day}'
def register(content,languages,slugs,sources,details):
    for i,trip in enumerate(TRIPS):
        slugs.append(('destinations',trip['slug']));sources.append([tuple(trip['source'])])
        details[trip['slug']]={'booking':'https://www.trip.com/t/kK2O3GfvuV2','booking_services':['hotels','flights','transfers','cars'],'poster_download':True,'place':{'name':trip['english'],'latitude':trip['geo'][0],'longitude':trip['geo'][1]}}
        for lang in languages:
            local=LOCAL[lang]
            title=trip['vi_title'] if lang=='vi' else trip['en_title'] if lang=='en' else f'{trip["city"]} · {local[1]} · {day_label(lang,1)}–{day_label(lang,trip["days"])}'
            intro=trip['vi_intro'] if lang=='vi' else trip['en_intro'] if lang=='en' else trip['city']+' · '+local[3]
            sections=VI_SECTIONS[i] if lang=='vi' else EN_SECTIONS[i] if lang=='en' else [(local[1],'; '.join(f'{day_label(lang,j+1)}: '+ ' → '.join(stops) for j,stops in enumerate(trip['stops']))),(local[2],local[3])]
            content[lang]['articles'].append([title,intro,sections])
